-- Only the trace table is kept; no character or account data is included.
-- Messages name NPCs and quest objectives only.
local function e(t, name, money, args, combat, kind)
    return {
        args = args or {},
        combat = combat == true,
        kind = kind or "event",
        money = money,
        name = name,
        t = t,
    }
end

